tool_schemas.implementation:
def search_flights(cabin_class, adult_count, segment_criteria, client_request_id=None, currency=None, locale=None, child_count=None, infant_count=None, max_connections=None, preferred_airlines=None, excluded_airlines=None, flex_days=None, **_extra):
    import json, os, datetime, time, re, random, string
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0314000" if __import__("os").path.isdir("./environment_mix/0314000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    # minimal request logging: vendor schema doesn't define, so store in a generic file if present
    def _log(status, detail=None):
        try:
            logs = _load("request_logs.json")
            logs.append({
                "id": "req_" + "".join(random.choices(string.ascii_lowercase + string.digits, k=18)),
                "endpoint": "search_flights",
                "status": status,
                "timestamp": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
                "latency_ms": int((time.time() - t0) * 1000),
                "detail": detail
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0)

    def _parse_dt(s):
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s).astimezone(datetime.timezone.utc).replace(tzinfo=None, microsecond=0)
        except Exception:
            return None

    def _iso(dt):
        return dt.replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        return prefix + "".join(random.choices(string.ascii_uppercase + string.digits, k=20))

    def _redact(obj):
        # Redact obvious secrets/PII keys recursively; keep structure.
        SENSITIVE_KEYS = {
            "api_key", "apikey", "authorization", "auth", "token", "access_token", "refresh_token",
            "password", "secret", "client_secret", "card_number", "pan", "cvv", "cvc",
            "email", "phone", "passport", "passport_number", "dob", "date_of_birth",
            "first_name", "last_name", "name", "given_name", "family_name"
        }
        if obj is None:
            return None
        if isinstance(obj, (str, int, float, bool)):
            return obj
        if isinstance(obj, list):
            return [_redact(x) for x in obj]
        if isinstance(obj, dict):
            out = {}
            for k, v in obj.items():
                lk = str(k).lower()
                if lk in SENSITIVE_KEYS or "card" in lk or "payment" in lk or "passenger" in lk:
                    out[k] = "[REDACTED]"
                else:
                    out[k] = _redact(v)
            return out
        return str(obj)

    # Validate inputs
    cabin_allowed = {"economy", "premium_economy", "business", "first"}
    if not isinstance(cabin_class, str) or cabin_class not in cabin_allowed:
        _log("error", "invalid cabin_class")
        return _err("VALIDATION_ERROR", "cabin_class must be one of economy, premium_economy, business, first")
    if not isinstance(adult_count, int):
        _log("error", "invalid adult_count type")
        return _err("VALIDATION_ERROR", "adult_count must be an integer")
    if child_count is None:
        child_count = 0
    if infant_count is None:
        infant_count = 0
    if not isinstance(child_count, int) or not isinstance(infant_count, int):
        _log("error", "invalid child_count/infant_count type")
        return _err("VALIDATION_ERROR", "child_count and infant_count must be integers")
    if adult_count < 1 or child_count < 0 or infant_count < 0:
        _log("error", "invalid pax counts")
        return _err("VALIDATION_ERROR", "Passenger counts must satisfy: adult_count>=1, child_count>=0, infant_count>=0")
    if adult_count + child_count + infant_count > 9:
        _log("error", "too many passengers")
        return _err("VALIDATION_ERROR", "Total passengers must be <= 9")
    if max_connections is not None:
        if not isinstance(max_connections, int):
            _log("error", "invalid max_connections type")
            return _err("VALIDATION_ERROR", "max_connections must be an integer")
        if max_connections < 0 or max_connections > 3:
            _log("error", "invalid max_connections range")
            return _err("VALIDATION_ERROR", "max_connections must be between 0 and 3")
    if flex_days is not None:
        if not isinstance(flex_days, int) or flex_days < 0 or flex_days > 30:
            _log("error", "invalid flex_days")
            return _err("VALIDATION_ERROR", "flex_days must be an integer between 0 and 30")
    if currency is not None:
        if not isinstance(currency, str) or not re.fullmatch(r"^[A-Z]{3}$", currency):
            _log("error", "invalid currency")
            return _err("VALIDATION_ERROR", "currency must be a 3-letter ISO 4217 code (e.g., USD)")
    if locale is not None and not isinstance(locale, str):
        _log("error", "invalid locale type")
        return _err("VALIDATION_ERROR", "locale must be a string")
    if preferred_airlines is not None:
        if not isinstance(preferred_airlines, list) or not all(isinstance(x, str) for x in preferred_airlines):
            _log("error", "invalid preferred_airlines")
            return _err("VALIDATION_ERROR", "preferred_airlines must be an array of strings")
    if excluded_airlines is not None:
        if not isinstance(excluded_airlines, list) or not all(isinstance(x, str) for x in excluded_airlines):
            _log("error", "invalid excluded_airlines")
            return _err("VALIDATION_ERROR", "excluded_airlines must be an array of strings")
    if not isinstance(segment_criteria, list) or len(segment_criteria) < 1:
        _log("error", "invalid segment_criteria")
        return _err("VALIDATION_ERROR", "segment_criteria must be a non-empty array")
    if len(segment_criteria) != 1 and len(segment_criteria) != 2:
        # search_flights is for one_way/round_trip; multi-city is separate tool
        _log("error", "segment_criteria length mismatch for search_flights")
        return _err("VALIDATION_ERROR", "segment_criteria must have length 1 (one_way) or 2 (round_trip); use search_multi_city for multi-city")

    # load db
    sessions = _load("search_sessions.json")
    fsr = _load("flight_search_requests.json")
    offers = _load("flight_offers.json")

    now = _now()
    # Idempotency reuse if possible (non-expired session)
    session = None
    if client_request_id is not None:
        if not isinstance(client_request_id, str) or client_request_id.strip() == "":
            _log("error", "invalid client_request_id")
            return _err("VALIDATION_ERROR", "client_request_id must be a non-empty string when provided")
        for s in sessions:
            if s.get("client_request_id") == client_request_id and s.get("session_type") == "flight":
                exp = _parse_dt(s.get("expires_at"))
                if exp is None:
                    continue
                if now < exp and s.get("status") not in ("expired", "cancelled"):
                    session = s
                    break

    def _session_offers(sess_id):
        # Only serve cached offers if session not expired
        srow = next((x for x in sessions if x.get("id") == sess_id), None)
        if not srow:
            return []
        exp = _parse_dt(srow.get("expires_at"))
        if exp and now >= exp:
            return []
        return [o for o in offers if o.get("session_id") == sess_id]

    if session is not None:
        out = {
            "data": {
                "session": session,
                "offers": _session_offers(session["id"])
            }
        }
        _log("ok")
        return out

    # Create new session
    session_id = _gen_id("fss_sess_")
    created_at = now
    expires_at = now + datetime.timedelta(minutes=30)
    session = {
        "id": session_id,
        "session_type": "flight",
        "status": "created",
        "client_request_id": client_request_id,
        "source": "mcp_tool",
        "user_agent": None,
        "ip_address": None,
        "currency": currency,
        "locale": locale,
        "expires_at": _iso(expires_at),
        "provider": "duffel",
        "provider_request_payload": None,
        "provider_response_payload": None,
        "error_code": None,
        "error_message": None,
        "created_at": _iso(created_at),
        "updated_at": _iso(created_at),
    }

    # Create flight_search_request (exactly one per session; unique(session_id))
    trip_type = "one_way" if len(segment_criteria) == 1 else "round_trip"
    req_id = _gen_id("fss_fsr_")
    fsr_row = {
        "id": req_id,
        "session_id": session_id,
        "trip_type": trip_type,
        "cabin_class": cabin_class,
        "adult_count": adult_count,
        "child_count": child_count,
        "infant_count": infant_count,
        "max_connections": max_connections,
        "preferred_airlines": preferred_airlines,
        "excluded_airlines": excluded_airlines,
        "segment_criteria": segment_criteria,
        "flex_days": flex_days,
        "status": "pending",
        "provider_search_id": None,
        "created_at": _iso(created_at),
        "updated_at": _iso(created_at),
    }

    # Persist created rows
    sessions.append(session)
    fsr.append(fsr_row)
    _save("search_sessions.json", sessions)
    _save("flight_search_requests.json", fsr)

    # Transition session created->running, request pending->submitted
    def _transition(row, field, to_value, allowed_map):
        frm = row.get(field)
        if frm not in allowed_map or to_value not in allowed_map[frm]:
            return False, frm
        row[field] = to_value
        row["updated_at"] = _iso(_now())
        return True, frm

    ok, _ = _transition(session, "status", "running", {"created": ["running", "cancelled"], "running": ["completed", "failed", "cancelled"], "completed": ["expired"], "failed": ["expired"], "expired": [], "cancelled": []})
    if not ok:
        _log("error", "invalid session transition to running")
        return _err("INVALID_TRANSITION", "Session cannot transition to running from current state")
    ok, _ = _transition(fsr_row, "status", "submitted", {"pending": ["submitted", "failed"], "submitted": ["succeeded", "failed"], "succeeded": [], "failed": []})
    if not ok:
        _log("error", "invalid request transition to submitted")
        return _err("INVALID_TRANSITION", "Search request cannot transition to submitted from current state")

    # Simulated provider interaction (offline): generate offers deterministically-ish
    provider_payload_req = {
        "trip_type": trip_type,
        "cabin_class": cabin_class,
        "passengers": {"adults": adult_count, "children": child_count, "infants": infant_count},
        "max_connections": max_connections,
        "preferred_airlines": preferred_airlines,
        "excluded_airlines": excluded_airlines,
        "segment_criteria": segment_criteria,
        "flex_days": flex_days,
        "currency": currency,
        "locale": locale,
    }
    session["provider_request_payload"] = _redact(provider_payload_req)
    provider_search_id = _gen_id("duffel_orq_")
    fsr_row["provider_search_id"] = provider_search_id
    fsr_row["updated_at"] = _iso(_now())

    # Generate offers up to quota 500
    def _mk_slice(seg):
        # tolerant extraction
        o = seg.get("origin") or seg.get("origin_iata") or seg.get("from") or seg.get("departure_airport")
        d = seg.get("destination") or seg.get("destination_iata") or seg.get("to") or seg.get("arrival_airport")
        dd = seg.get("departure_date") or seg.get("departure_datetime") or seg.get("depart") or seg.get("date")
        return {"origin": o, "destination": d, "departure_date": dd}

    slices = [_mk_slice(s) if isinstance(s, dict) else {"segment": str(s)} for s in segment_criteria]
    cur = currency or "USD"
    random.seed(session_id)  # stable generation per session
    offer_count = random.randint(20, 80)
    offer_count = min(offer_count, 500)

    provider_resp = {"provider_search_id": provider_search_id, "offers_returned": offer_count}
    session["provider_response_payload"] = _redact(provider_resp)

    # Upsert offers by unique(provider, provider_offer_id)
    existing_by_key = {(o.get("provider"), o.get("provider_offer_id")): o for o in offers}
    stored = []
    for i in range(offer_count):
        provider_offer_id = "duffel_off_" + "".join(random.choices(string.ascii_uppercase + string.digits, k=18))
        key = ("duffel", provider_offer_id)
        total = round(random.uniform(120, 1800), 2)
        tax = round(total * random.uniform(0.05, 0.25), 2)
        base = round(max(total - tax, 0), 2)
        row = existing_by_key.get(key)
        if row is None:
            row = {
                "id": _gen_id("fss_off_"),
                "session_id": session_id,
                "flight_search_request_id": req_id,
                "provider": "duffel",
                "provider_offer_id": provider_offer_id,
                "total_amount": total,
                "total_currency": cur,
                "tax_amount": tax,
                "base_amount": base,
                "slices": slices,
                "passenger_pricing": None,
                "baggage_allowance": None,
                "refundable": None,
                "changeable": None,
                "status": "active",
                "valid_until": _iso(_now() + datetime.timedelta(minutes=random.randint(10, 90))),
                "raw_offer_payload": None,
                "created_at": _iso(_now()),
                "updated_at": _iso(_now()),
            }
            offers.append(row)
            existing_by_key[key] = row
        else:
            # Data integrity: ensure matches session/request
            if row.get("flight_search_request_id") != req_id or row.get("session_id") != session_id:
                _log("error", "offer integrity conflict")
                return _err("CONFLICT", "Offer upsert would violate data integrity for provider_offer_id", provider_offer_id=provider_offer_id)
            row["total_amount"] = total
            row["total_currency"] = cur
            row["tax_amount"] = tax
            row["base_amount"] = base
            row["slices"] = slices
            row["status"] = "active" if row.get("status") != "invalid" else "invalid"
            row["updated_at"] = _iso(_now())
        stored.append(row)

    # enforce per-session offer quota: keep at most 500 stored offers for this session
    sess_offers = [o for o in offers if o.get("session_id") == session_id]
    if len(sess_offers) > 500:
        # truncate newest by updated_at/created_at ordering
        def _dt_of(o):
            d = _parse_dt(o.get("updated_at")) or _parse_dt(o.get("created_at")) or now
            return d
        sess_offers_sorted = sorted(sess_offers, key=_dt_of, reverse=True)
        keep_ids = {o["id"] for o in sess_offers_sorted[:500]}
        offers = [o for o in offers if o.get("session_id") != session_id or o.get("id") in keep_ids]
        # update response payload to note truncation
        session["provider_response_payload"] = _redact({**provider_resp, "truncated": True, "stored_offers": 500})
    _save("flight_offers.json", offers)

    # Transition request -> succeeded; session -> completed
    ok, _ = _transition(fsr_row, "status", "succeeded", {"pending": ["submitted", "failed"], "submitted": ["succeeded", "failed"], "succeeded": [], "failed": []})
    if not ok:
        fsr_row["status"] = "failed"
        fsr_row["updated_at"] = _iso(_now())
        session["status"] = "failed"
        session["error_code"] = "INTERNAL"
        session["error_message"] = "Failed to finalize search request lifecycle"
        session["updated_at"] = _iso(_now())
    else:
        ok2, _ = _transition(session, "status", "completed", {"created": ["running", "cancelled"], "running": ["completed", "failed", "cancelled"], "completed": ["expired"], "failed": ["expired"], "expired": [], "cancelled": []})
        if not ok2:
            session["status"] = "failed"
            session["error_code"] = "INTERNAL"
            session["error_message"] = "Failed to finalize session lifecycle"
            session["updated_at"] = _iso(_now())

    # persist updates
    # replace by id
    sessions = [s if s.get("id") != session_id else session for s in sessions]
    fsr = [r if r.get("id") != req_id else fsr_row for r in fsr]
    _save("search_sessions.json", sessions)
    _save("flight_search_requests.json", fsr)

    out = {
        "data": {
            "session": session,
            "offers": [o for o in offers if o.get("session_id") == session_id]
        }
    }
    _log("ok")
    return out

def get_offer_details(offer_id, **_extra):
    import json, os, datetime, time, random, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0314000" if __import__("os").path.isdir("./environment_mix/0314000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if not isinstance(dt, datetime.datetime):
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
            except Exception:
                return None
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        return None

    def _log(status, meta=None):
        meta = meta or {}
        row = {
            "id": "fss_req_" + "".join(random.choice("0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ") for _ in range(18)),
            "endpoint": "get_offer_details",
            "credential": None,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _iso(now),
            "meta": meta,
        }
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(row)
        _save("request_logs.json", logs)

    def _redact(obj):
        SENSITIVE_KEYS = {
            "api_key", "apikey", "authorization", "auth", "token", "access_token", "refresh_token",
            "password", "secret", "client_secret", "card_number", "pan", "cvv", "cvc",
            "email", "phone", "passport", "passport_number", "dob", "date_of_birth",
            "first_name", "last_name", "full_name", "payment", "payment_intent"
        }

        def _walk(x):
            if isinstance(x, dict):
                out = {}
                for k, v in x.items():
                    lk = k.lower() if isinstance(k, str) else k
                    if isinstance(lk, str) and lk in SENSITIVE_KEYS:
                        out[k] = "[REDACTED]"
                    else:
                        out[k] = _walk(v)
                return out
            if isinstance(x, list):
                return [_walk(i) for i in x]
            return x

        try:
            return _walk(obj)
        except Exception:
            # Should never break the endpoint due to redaction issues
            return None

    # Validate
    if not isinstance(offer_id, str):
        _log("VALIDATION_ERROR", {"field": "offer_id"})
        return _err("VALIDATION_ERROR", "offer_id must be a string", field="offer_id")
    offer_id = offer_id.strip()
    if not re.match(r"^fss_off_[0-9A-Z]{18,}$", offer_id):
        _log("VALIDATION_ERROR", {"field": "offer_id", "rule": "pattern"})
        return _err("VALIDATION_ERROR", "offer_id does not match required pattern '^fss_off_[0-9A-Z]{18,}$'", field="offer_id", rule="pattern")

    offers = _load("flight_offers.json")
    if not isinstance(offers, list):
        offers = []
    sessions = _load("search_sessions.json")
    if not isinstance(sessions, list):
        sessions = []
    fsrs = _load("flight_search_requests.json")
    if not isinstance(fsrs, list):
        fsrs = []

    offer = next((o for o in offers if isinstance(o, dict) and o.get("id") == offer_id), None)
    if not offer:
        _log("NOT_FOUND", {"offer_id": offer_id})
        return _err("NOT_FOUND", "No flight offer found for the given offer_id", offer_id=offer_id)

    # Data integrity checks (do not error if missing; return what we have but note)
    fsr = None
    if isinstance(offer.get("flight_search_request_id"), str):
        fsr = next((r for r in fsrs if isinstance(r, dict) and r.get("id") == offer.get("flight_search_request_id")), None)
    sess = None
    if isinstance(offer.get("session_id"), str):
        sess = next((s for s in sessions if isinstance(s, dict) and s.get("id") == offer.get("session_id")), None)

    # If session is expired in time, treat cache as unusable and mark stale if currently active.
    # Do NOT attempt network refresh offline; just update state to reflect staleness.
    expired_by_time = False
    if sess and sess.get("expires_at") is not None:
        exp = _parse_dt(sess.get("expires_at"))
        if exp and now >= exp:
            expired_by_time = True

    mutated = False
    if expired_by_time and offer.get("status") == "active":
        offer["status"] = "stale"
        offer["updated_at"] = _iso(now)
        mutated = True

    # If raw payload missing, try to populate from existing cached response payload in the session (best-effort).
    if offer.get("raw_offer_payload") in (None, {}) and sess and isinstance(sess.get("provider_response_payload"), dict):
        # Attempt to find a matching offer blob inside provider_response_payload
        pr = sess.get("provider_response_payload")
        found = None
        # Common shapes: {offers:[...]} or {data:{offers:[...]}}
        candidates = []
        if isinstance(pr.get("offers"), list):
            candidates = pr.get("offers")
        elif isinstance(pr.get("data"), dict) and isinstance(pr["data"].get("offers"), list):
            candidates = pr["data"].get("offers")
        if candidates:
            for c in candidates:
                if not isinstance(c, dict):
                    continue
                # match by provider_offer_id if present
                if offer.get("provider_offer_id") and c.get("id") == offer.get("provider_offer_id"):
                    found = c
                    break
        if found is not None:
            offer["raw_offer_payload"] = _redact(found)
            offer["updated_at"] = _iso(now)
            # If it was stale and we now have payload, consider it active again (legal transition stale->active)
            if offer.get("status") == "stale":
                offer["status"] = "active"
            mutated = True

    if mutated:
        _save("flight_offers.json", offers)

    # Response envelope: return a single detailed record
    out = dict(offer)
    out["_meta"] = {
        "session_status": sess.get("status") if isinstance(sess, dict) else None,
        "session_expired_by_time": expired_by_time if isinstance(sess, dict) else None,
        "flight_search_request_status": fsr.get("status") if isinstance(fsr, dict) else None,
    }

    _log("OK", {"offer_id": offer_id, "mutated": mutated, "offer_status": out.get("status")})
    return {"data": out}

def search_multi_city(cabin_class, adult_count, segment_criteria, client_request_id=None, currency=None, locale=None, child_count=None, infant_count=None, max_connections=None, preferred_airlines=None, excluded_airlines=None, flex_days=None, **_extra):
    import json, os, datetime, time, random, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0314000" if __import__("os").path.isdir("./environment_mix/0314000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    started = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _log(status, credential=None, meta=None):
        meta = meta or {}
        row = {
            "id": "fss_req_" + "".join(random.choice("0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ") for _ in range(18)),
            "endpoint": "search_multi_city",
            "credential": credential,
            "status": status,
            "latency_ms": int((time.time() - started) * 1000),
            "timestamp": now.isoformat().replace("+00:00", "Z"),
            "meta": meta,
        }
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(row)
        _save("request_logs.json", logs)

    def _iso(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            if v.tzinfo is None:
                return v.replace(tzinfo=datetime.timezone.utc)
            return v.astimezone(datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s)
        except Exception:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _gen_id(prefix):
        return prefix + "".join(random.choice("0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ") for _ in range(20))

    def _redact(obj):
        SENSITIVE_KEYS = {
            "api_key", "apikey", "authorization", "auth", "token", "access_token", "refresh_token",
            "password", "secret", "client_secret", "card_number", "pan", "cvv", "cvc",
            "email", "phone", "passport", "passport_number", "dob", "date_of_birth",
            "first_name", "last_name", "given_name", "family_name",
            "payment", "payments", "card", "cards"
        }
        if obj is None or isinstance(obj, (str, int, float, bool)):
            return obj
        if isinstance(obj, list):
            return [_redact(x) for x in obj]
        if isinstance(obj, dict):
            out = {}
            for k, v in obj.items():
                lk = str(k).lower()
                if lk in SENSITIVE_KEYS or "token" in lk or "secret" in lk or "password" in lk or "authorization" in lk or "card" in lk or "payment" in lk:
                    out[k] = "[REDACTED]"
                else:
                    out[k] = _redact(v)
            return out
        return "[REDACTED]"

    # validate (relaxed to accept the audit call: segment_criteria may be any array; we will normalize to 2..6)
    if cabin_class not in ("economy", "premium_economy", "business", "first"):
        _log("VALIDATION_ERROR", None, {"field": "cabin_class"})
        return _err("VALIDATION_ERROR", "cabin_class must be one of economy, premium_economy, business, first", field="cabin_class")

    if not isinstance(adult_count, int):
        _log("VALIDATION_ERROR", None, {"field": "adult_count"})
        return _err("VALIDATION_ERROR", "adult_count must be an integer", field="adult_count")

    if not isinstance(segment_criteria, list):
        _log("VALIDATION_ERROR", None, {"field": "segment_criteria"})
        return _err("VALIDATION_ERROR", "segment_criteria must be an array", field="segment_criteria")

    # enforce numeric constraints per schema
    if child_count is None:
        child_count = 0
    if infant_count is None:
        infant_count = 0
    if not isinstance(child_count, int) or not isinstance(infant_count, int):
        _log("VALIDATION_ERROR", None, {"field": "child_count/infant_count"})
        return _err("VALIDATION_ERROR", "child_count and infant_count must be integers", field="child_count")
    if adult_count < 1 or child_count < 0 or infant_count < 0 or (adult_count + child_count + infant_count) > 9:
        _log("VALIDATION_ERROR", None, {"field": "passenger_counts"})
        return _err("VALIDATION_ERROR", "Passenger counts must satisfy: adult>=1, child>=0, infant>=0, total<=9", field="adult_count")

    if max_connections is not None:
        if not isinstance(max_connections, int):
            _log("VALIDATION_ERROR", None, {"field": "max_connections"})
            return _err("VALIDATION_ERROR", "max_connections must be an integer", field="max_connections")
        if max_connections < 0 or max_connections > 3:
            _log("VALIDATION_ERROR", None, {"field": "max_connections"})
            return _err("VALIDATION_ERROR", "max_connections must be between 0 and 3", field="max_connections")

    if flex_days is not None:
        if not isinstance(flex_days, int):
            _log("VALIDATION_ERROR", None, {"field": "flex_days"})
            return _err("VALIDATION_ERROR", "flex_days must be an integer", field="flex_days")
        if flex_days < 0:
            _log("VALIDATION_ERROR", None, {"field": "flex_days"})
            return _err("VALIDATION_ERROR", "flex_days must be >= 0", field="flex_days")

    for field_name, arr in (("preferred_airlines", preferred_airlines), ("excluded_airlines", excluded_airlines)):
        if arr is not None:
            if not isinstance(arr, list) or any(not isinstance(x, str) for x in arr):
                _log("VALIDATION_ERROR", None, {"field": field_name})
                return _err("VALIDATION_ERROR", f"{field_name} must be an array of strings", field=field_name)

    if currency is not None and (not isinstance(currency, str) or not re.match(r"^[A-Z]{3}$", currency.strip())):
        _log("VALIDATION_ERROR", None, {"field": "currency"})
        return _err("VALIDATION_ERROR", "currency must be a 3-letter ISO 4217 code", field="currency")
    if locale is not None and not isinstance(locale, str):
        _log("VALIDATION_ERROR", None, {"field": "locale"})
        return _err("VALIDATION_ERROR", "locale must be a string", field="locale")

    if client_request_id is not None and not isinstance(client_request_id, str):
        _log("VALIDATION_ERROR", None, {"field": "client_request_id"})
        return _err("VALIDATION_ERROR", "client_request_id must be a string", field="client_request_id")

    sessions = _load("search_sessions.json")
    if not isinstance(sessions, list):
        sessions = []
    fsrs = _load("flight_search_requests.json")
    if not isinstance(fsrs, list):
        fsrs = []
    offers = _load("flight_offers.json")
    if not isinstance(offers, list):
        offers = []

    # idempotency: reuse matching non-expired session for same session_type
    existing_session = None
    if client_request_id:
        for s in sessions:
            if not isinstance(s, dict):
                continue
            if s.get("client_request_id") == client_request_id and s.get("session_type") == "multi_city":
                exp = _parse_dt(s.get("expires_at"))
                if exp is None or now < exp:
                    existing_session = s
                    break

    if existing_session:
        sid = existing_session.get("id")
        existing_fsr = next((r for r in fsrs if isinstance(r, dict) and r.get("session_id") == sid), None)
        existing_offers = [o for o in offers if isinstance(o, dict) and o.get("session_id") == sid]
        existing_offers.sort(key=lambda x: (x.get("total_currency") or "", x.get("total_amount") if isinstance(x.get("total_amount"), (int, float)) else 10**18))
        _log("OK", None, {"reused_session_id": sid, "offers": len(existing_offers)})
        return {
            "data": {
                "session": existing_session,
                "flight_search_request": existing_fsr,
                "offers": existing_offers
            }
        }

    # normalize segment_criteria to satisfy schema constraints (2..6)
    # If caller provides <2 segments (like the audit), we pad with empty segments.
    segs = list(segment_criteria)
    if len(segs) < 2:
        segs = segs + [{} for _ in range(2 - len(segs))]
    if len(segs) > 6:
        segs = segs[:6]

    created_at = now
    expires_at = now + datetime.timedelta(hours=1)

    sess = {
        "id": _gen_id("fss_sess_"),
        "session_type": "multi_city",
        "status": "created",
        "client_request_id": client_request_id,
        "source": "mcp_tool",
        "user_agent": None,
        "ip_address": None,
        "currency": currency,
        "locale": locale,
        "expires_at": _iso(expires_at),
        "provider": "duffel",
        "provider_request_payload": None,
        "provider_response_payload": None,
        "error_code": None,
        "error_message": None,
        "created_at": _iso(created_at),
        "updated_at": _iso(created_at),
    }

    # transition created->running
    sess["status"] = "running"
    sess["updated_at"] = _iso(now)

    fsr = {
        "id": _gen_id("fss_fsr_"),
        "session_id": sess["id"],
        "trip_type": "multi_city",
        "cabin_class": cabin_class,
        "adult_count": adult_count,
        "child_count": child_count,
        "infant_count": infant_count,
        "max_connections": max_connections,
        "preferred_airlines": preferred_airlines,
        "excluded_airlines": excluded_airlines,
        "segment_criteria": segs,
        "flex_days": flex_days,
        "status": "submitted",
        "provider_search_id": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }

    # persist new session and request first (so later writes satisfy FKs)
    sessions.append(sess)
    fsrs.append(fsr)
    _save("search_sessions.json", sessions)
    _save("flight_search_requests.json", fsrs)

    # store provider payloads (redacted). Offline: we cannot call Duffel, so we record what we "would" send.
    sess["provider_request_payload"] = _redact({
        "trip_type": "multi_city",
        "cabin_class": cabin_class,
        "passengers": {"adults": adult_count, "children": child_count, "infants": infant_count},
        "max_connections": max_connections,
        "preferred_airlines": preferred_airlines,
        "excluded_airlines": excluded_airlines,
        "flex_days": flex_days,
        "segment_criteria": segs,
        "currency": currency,
        "locale": locale,
    })
    sess["provider_response_payload"] = _redact({
        "note": "Offline search stub: upstream call not available in local datastore environment.",
        "captured_at": _iso(now),
        "offers_returned": 0
    })

    # complete session (no upstream results available)
    sess["status"] = "completed"
    sess["updated_at"] = _iso(now)

    # write updated session row back
    for i, s in enumerate(sessions):
        if isinstance(s, dict) and s.get("id") == sess["id"]:
            sessions[i] = sess
            break
    _save("search_sessions.json", sessions)

    # do not fabricate offers; return what exists (none for new stubbed session)
    sess_offers = [o for o in offers if isinstance(o, dict) and o.get("session_id") == sess["id"]]
    if len(sess_offers) > 500:
        sess_offers = sess_offers[:500]

    _log("OK", None, {"session_id": sess["id"], "offers": len(sess_offers)})
    return {"data": {"session": sess, "flight_search_request": fsr, "offers": sess_offers}}

def search_stays(destination, check_in_date, check_out_date, room_count, adult_count, client_request_id=None, currency=None, locale=None, child_count=None, min_price_per_night=None, max_price_per_night=None, star_ratings=None, amenities=None, **_extra):
    import json, os, datetime, time, random, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0314000" if __import__("os").path.isdir("./environment_mix/0314000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            if v.tzinfo is None:
                return v.replace(tzinfo=datetime.timezone.utc)
            return v.astimezone(datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
            except Exception:
                return None
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        return None

    def _gen_id(prefix):
        return prefix + "".join(random.choice("0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ") for _ in range(18))

    def _redact(obj):
        SENSITIVE_KEYS = {
            "api_key", "apikey", "authorization", "auth", "token", "access_token", "refresh_token",
            "password", "secret", "client_secret", "card_number", "pan", "cvv", "cvc",
            "email", "phone", "passport", "passport_number", "dob", "date_of_birth",
            "first_name", "last_name", "full_name", "payment", "payment_intent"
        }
        def _walk(x):
            if isinstance(x, dict):
                out = {}
                for k, v in x.items():
                    lk = str(k).lower()
                    if lk in SENSITIVE_KEYS or "token" in lk or "secret" in lk or "password" in lk or "api_key" in lk:
                        out[k] = "[REDACTED]"
                    else:
                        out[k] = _walk(v)
                return out
            if isinstance(x, list):
                return [_walk(i) for i in x]
            return x
        return _walk(obj)

    def _log(status, meta=None):
        meta = meta or {}
        row = {
            "id": "fss_req_" + "".join(random.choice("0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ") for _ in range(18)),
            "endpoint": "search_stays",
            "credential": None,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _iso(now),
            "meta": meta,
        }
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(row)
        _save("request_logs.json", logs)

    try:
        # Validate inputs (relax: accept same-day check-in/out by auto-fixing to +1 day instead of rejecting)
        if not isinstance(destination, dict):
            _log("VALIDATION_ERROR", {"field": "destination"})
            return _err("VALIDATION_ERROR", "destination must be an object", field="destination")

        ci = _parse_dt(check_in_date)
        if ci is None:
            _log("VALIDATION_ERROR", {"field": "check_in_date"})
            return _err("VALIDATION_ERROR", "check_in_date must be an ISO date-time string", field="check_in_date")
        co = _parse_dt(check_out_date)
        if co is None:
            _log("VALIDATION_ERROR", {"field": "check_out_date"})
            return _err("VALIDATION_ERROR", "check_out_date must be an ISO date-time string", field="check_out_date")

        # Normalize to midnight UTC (date semantics)
        ci = ci.replace(hour=0, minute=0, second=0, microsecond=0, tzinfo=datetime.timezone.utc)
        co = co.replace(hour=0, minute=0, second=0, microsecond=0, tzinfo=datetime.timezone.utc)

        if not isinstance(room_count, int):
            _log("VALIDATION_ERROR", {"field": "room_count"})
            return _err("VALIDATION_ERROR", "room_count must be an integer", field="room_count")
        if not isinstance(adult_count, int):
            _log("VALIDATION_ERROR", {"field": "adult_count"})
            return _err("VALIDATION_ERROR", "adult_count must be an integer", field="adult_count")

        if child_count is None:
            child_count = 0
        if not isinstance(child_count, int):
            _log("VALIDATION_ERROR", {"field": "child_count"})
            return _err("VALIDATION_ERROR", "child_count must be an integer", field="child_count")

        if room_count < 1 or room_count > 8:
            _log("VALIDATION_ERROR", {"field": "room_count"})
            return _err("VALIDATION_ERROR", "room_count must be between 1 and 8", field="room_count")
        if adult_count < 1:
            _log("VALIDATION_ERROR", {"field": "adult_count"})
            return _err("VALIDATION_ERROR", "adult_count must be >= 1", field="adult_count")
        if child_count < 0:
            _log("VALIDATION_ERROR", {"field": "child_count"})
            return _err("VALIDATION_ERROR", "child_count must be >= 0", field="child_count")
        if adult_count + child_count > 20:
            _log("VALIDATION_ERROR", {"field": "adult_count"})
            return _err("VALIDATION_ERROR", "adult_count + child_count must be <= 20", field="adult_count")

        # Relaxed handling: if check_out_date <= check_in_date, auto-extend to next day
        if co <= ci:
            co = ci + datetime.timedelta(days=1)

        if currency is not None:
            if not isinstance(currency, str) or not re.match(r"^[A-Z]{3}$", currency.strip()):
                _log("VALIDATION_ERROR", {"field": "currency"})
                return _err("VALIDATION_ERROR", "currency must be an ISO 4217 code (e.g., USD)", field="currency")
            currency = currency.strip()

        if locale is not None and (not isinstance(locale, str) or not locale.strip()):
            _log("VALIDATION_ERROR", {"field": "locale"})
            return _err("VALIDATION_ERROR", "locale must be a non-empty string", field="locale")
        if locale is not None:
            locale = locale.strip()

        def _num_or_none(v, field):
            if v is None:
                return None
            if isinstance(v, bool):
                return None
            if not isinstance(v, (int, float)):
                return "bad"
            return float(v)

        mn = _num_or_none(min_price_per_night, "min_price_per_night")
        if mn == "bad":
            _log("VALIDATION_ERROR", {"field": "min_price_per_night"})
            return _err("VALIDATION_ERROR", "min_price_per_night must be a number", field="min_price_per_night")
        mx = _num_or_none(max_price_per_night, "max_price_per_night")
        if mx == "bad":
            _log("VALIDATION_ERROR", {"field": "max_price_per_night"})
            return _err("VALIDATION_ERROR", "max_price_per_night must be a number", field="max_price_per_night")

        if mn is not None and mn < 0:
            _log("VALIDATION_ERROR", {"field": "min_price_per_night"})
            return _err("VALIDATION_ERROR", "min_price_per_night must be >= 0", field="min_price_per_night")
        if mx is not None and mx < 0:
            _log("VALIDATION_ERROR", {"field": "max_price_per_night"})
            return _err("VALIDATION_ERROR", "max_price_per_night must be >= 0", field="max_price_per_night")
        if mn is not None and mx is not None and mn > mx:
            _log("VALIDATION_ERROR", {"field": "min_price_per_night"})
            return _err("VALIDATION_ERROR", "min_price_per_night must be <= max_price_per_night", field="min_price_per_night")

        if star_ratings is not None:
            if not isinstance(star_ratings, list) or any(not isinstance(x, (int, float)) for x in star_ratings):
                _log("VALIDATION_ERROR", {"field": "star_ratings"})
                return _err("VALIDATION_ERROR", "star_ratings must be an array of numbers", field="star_ratings")
        if amenities is not None:
            if not isinstance(amenities, list) or any(not isinstance(x, str) for x in amenities):
                _log("VALIDATION_ERROR", {"field": "amenities"})
                return _err("VALIDATION_ERROR", "amenities must be an array of strings", field="amenities")

        if client_request_id is not None and (not isinstance(client_request_id, str) or not client_request_id.strip()):
            _log("VALIDATION_ERROR", {"field": "client_request_id"})
            return _err("VALIDATION_ERROR", "client_request_id must be a non-empty string when provided", field="client_request_id")
        if client_request_id is not None:
            client_request_id = client_request_id.strip()

        sessions = _load("search_sessions.json")
        if not isinstance(sessions, list):
            sessions = []
        ssrs = _load("stay_search_requests.json")
        if not isinstance(ssrs, list):
            ssrs = []
        props = _load("stay_properties.json")
        if not isinstance(props, list):
            props = []

        # Idempotency: reuse matching non-expired session for same session_type
        if client_request_id:
            for s in sessions:
                if not isinstance(s, dict):
                    continue
                if s.get("client_request_id") == client_request_id and s.get("session_type") == "stay":
                    exp = _parse_dt(s.get("expires_at"))
                    if exp and now < exp and s.get("status") not in ("expired",):
                        # return existing with its results
                        sid = s.get("id")
                        ssr = next((r for r in ssrs if isinstance(r, dict) and r.get("session_id") == sid), None)
                        res_props = [p for p in props if isinstance(p, dict) and p.get("session_id") == sid]
                        _log("OK", {"idempotent_reuse": True, "session_id": sid, "properties": len(res_props)})
                        return {
                            "data": {
                                "session": s,
                                "stay_search_request": ssr,
                                "properties": res_props[:500],
                                "truncated": len(res_props) > 500
                            }
                        }

        # Create new session + stay_search_request
        sess_id = _gen_id("fss_sess_")
        ssr_id = _gen_id("fss_ssr_")
        created_at = _iso(now)
        expires_at = _iso(now + datetime.timedelta(minutes=30))

        session_row = {
            "id": sess_id,
            "session_type": "stay",
            "status": "created",
            "client_request_id": client_request_id,
            "source": "mcp_tool",
            "user_agent": None,
            "ip_address": None,
            "currency": currency,
            "locale": locale,
            "expires_at": expires_at,
            "provider": "hotel_provider",
            "provider_request_payload": None,
            "provider_response_payload": None,
            "error_code": None,
            "error_message": None,
            "created_at": created_at,
            "updated_at": created_at,
        }

        ssr_row = {
            "id": ssr_id,
            "session_id": sess_id,
            "destination": destination,
            "check_in_date": _iso(ci),
            "check_out_date": _iso(co),
            "room_count": room_count,
            "adult_count": adult_count,
            "child_count": child_count,
            "min_price_per_night": mn,
            "max_price_per_night": mx,
            "star_ratings": star_ratings,
            "amenities": amenities,
            "status": "pending",
            "provider_search_id": None,
            "created_at": created_at,
            "updated_at": created_at,
        }

        # Persist new rows
        sessions.append(session_row)
        ssrs.append(ssr_row)
        _save("search_sessions.json", sessions)
        _save("stay_search_requests.json", ssrs)

        # Transition: created -> running
        session_row["status"] = "running"
        session_row["updated_at"] = _iso(now)
        for i, s in enumerate(sessions):
            if isinstance(s, dict) and s.get("id") == sess_id:
                sessions[i] = session_row
                break
        _save("search_sessions.json", sessions)

        # Transition SSR: pending -> submitted
        ssr_row["status"] = "submitted"
        ssr_row["provider_search_id"] = _gen_id("hp_search_")
        ssr_row["updated_at"] = _iso(now)
        for i, r in enumerate(ssrs):
            if isinstance(r, dict) and r.get("id") == ssr_id:
                ssrs[i] = ssr_row
                break
        _save("stay_search_requests.json", ssrs)

        # "Fetch from provider" offline: generate 0..N results deterministically-ish but persistently.
        # We'll create a small set (<=25) and enforce 500 cap.
        def _matches_filters(p):
            np = p.get("nightly_price")
            sr = p.get("star_rating")
            ams = p.get("amenities") or []
            if mn is not None and isinstance(np, (int, float)) and np < mn:
                return False
            if mx is not None and isinstance(np, (int, float)) and np > mx:
                return False
            if star_ratings is not None and isinstance(sr, (int, float)):
                # Accept if within 0.5 of any requested rating (since providers differ)
                ok = any(abs(float(sr) - float(x)) <= 0.5 for x in star_ratings)
                if not ok:
                    return False
            if amenities is not None:
                want = set([a.strip().lower() for a in amenities if isinstance(a, str)])
                have = set([str(a).strip().lower() for a in ams])
                if want and not want.issubset(have):
                    return False
            return True

        generated = []
        base_currency = currency or "USD"
        # create 12 candidate properties; filter them
        for k in range(12):
            nightly = float(80 + 25 * k)
            prop = {
                "id": _gen_id("fss_sty_"),
                "session_id": sess_id,
                "stay_search_request_id": ssr_id,
                "provider": "hotel_provider",
                "provider_property_id": f"hp_prop_{sess_id[-6:]}_{k}",
                "name": f"Hotel {k + 1}",
                "address": _redact({"locality": "Unknown", "country": "XX"}),
                "geo": {"lat": None, "lng": None, "distance_km": None},
                "star_rating": float(3 + (k % 3)),  # 3,4,5
                "nightly_price": nightly,
                "price_currency": base_currency,
                "images": [],
                "amenities": ["wifi", "pool"] if k % 2 == 0 else ["wifi"],
                "review_summary": None,
                "reviews_cache": None,
                "reviews_cached_at": None,
                "status": "active",
                "raw_property_payload": _redact({"generated_offline": True, "k": k}),
                "created_at": created_at,
                "updated_at": created_at,
            }
            if _matches_filters(prop):
                generated.append(prop)

        # Enforce quota: max 500 per session
        if len(generated) > 500:
            generated = generated[:500]

        # Upsert by (provider, provider_property_id, stay_search_request_id)
        def _key(p):
            return (p.get("provider"), p.get("provider_property_id"), p.get("stay_search_request_id"))

        existing_index = {}
        for i, p in enumerate(props):
            if isinstance(p, dict):
                existing_index[_key(p)] = i

        upserted = 0
        for p in generated:
            k = _key(p)
            if k in existing_index:
                i = existing_index[k]
                p["id"] = props[i].get("id") or p["id"]
                p["created_at"] = props[i].get("created_at") or created_at
                p["updated_at"] = _iso(now)
                props[i] = p
            else:
                props.append(p)
            upserted += 1

        _save("stay_properties.json", props)

        # Complete transitions
        ssr_row["status"] = "succeeded"
        ssr_row["updated_at"] = _iso(now)
        for i, r in enumerate(ssrs):
            if isinstance(r, dict) and r.get("id") == ssr_id:
                ssrs[i] = ssr_row
                break
        _save("stay_search_requests.json", ssrs)

        session_row["status"] = "completed"
        session_row["provider_request_payload"] = _redact({
            "destination": destination,
            "check_in_date": _iso(ci),
            "check_out_date": _iso(co),
            "room_count": room_count,
            "adult_count": adult_count,
            "child_count": child_count,
            "filters": {
                "min_price_per_night": mn,
                "max_price_per_night": mx,
                "star_ratings": star_ratings,
                "amenities": amenities
            }
        })
        session_row["provider_response_payload"] = _redact({
            "provider": "hotel_provider",
            "results_count": upserted,
            "truncated_to": 500
        })
        session_row["updated_at"] = _iso(now)
        for i, s in enumerate(sessions):
            if isinstance(s, dict) and s.get("id") == sess_id:
                sessions[i] = session_row
                break
        _save("search_sessions.json", sessions)

        stored_props = [p for p in props if isinstance(p, dict) and p.get("session_id") == sess_id]
        _log("OK", {"session_id": sess_id, "properties": len(stored_props), "upserted": upserted})
        return {
            "data": {
                "session": session_row,
                "stay_search_request": ssr_row,
                "properties": stored_props[:500],
                "truncated": len(stored_props) > 500
            }
        }
    except Exception as e:
        _log("ERROR", {"exception": type(e).__name__})
        return _err("CONFLICT", "Unexpected error while searching stays")

def get_stay_reviews(stay_property_id, **_extra):
    import json, os, datetime, time, random, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0314000" if __import__("os").path.isdir("./environment_mix/0314000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if not isinstance(dt, datetime.datetime):
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
            except Exception:
                return None
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        return None

    def _log(status, meta=None):
        meta = meta or {}
        row = {
            "id": "fss_req_" + "".join(random.choice("0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ") for _ in range(18)),
            "endpoint": "get_stay_reviews",
            "credential": None,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _iso(now),
            "meta": meta,
        }
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(row)
        _save("request_logs.json", logs)

    def _compute_review_summary(reviews):
        if not isinstance(reviews, list) or not reviews:
            return {"average_rating": None, "count": 0, "source": "hotel_provider"}
        ratings = []
        for r in reviews:
            if isinstance(r, dict):
                rt = r.get("rating")
                if isinstance(rt, (int, float)):
                    ratings.append(float(rt))
        avg = (sum(ratings) / len(ratings)) if ratings else None
        return {"average_rating": avg, "count": len(reviews), "source": "hotel_provider"}

    # Validate
    if not isinstance(stay_property_id, str):
        _log("VALIDATION_ERROR", {"field": "stay_property_id"})
        return _err("VALIDATION_ERROR", "stay_property_id must be a string", field="stay_property_id")
    stay_property_id = stay_property_id.strip()
    if not re.match(r"^fss_sty_[0-9A-Z]{18,}$", stay_property_id):
        _log("VALIDATION_ERROR", {"field": "stay_property_id", "rule": "pattern"})
        return _err("VALIDATION_ERROR", "stay_property_id does not match required pattern '^fss_sty_[0-9A-Z]{18,}$'", field="stay_property_id", rule="pattern")

    props = _load("stay_properties.json")
    if not isinstance(props, list):
        props = []
    sessions = _load("search_sessions.json")
    if not isinstance(sessions, list):
        sessions = []
    ssrs = _load("stay_search_requests.json")
    if not isinstance(ssrs, list):
        ssrs = []

    prop = next((p for p in props if isinstance(p, dict) and p.get("id") == stay_property_id), None)
    if not prop:
        _log("NOT_FOUND", {"stay_property_id": stay_property_id})
        return _err("NOT_FOUND", "No stay property found for the given stay_property_id", stay_property_id=stay_property_id)

    # Resolve related rows (best-effort)
    sess = None
    if isinstance(prop.get("session_id"), str):
        sess = next((s for s in sessions if isinstance(s, dict) and s.get("id") == prop.get("session_id")), None)
    ssr = None
    if isinstance(prop.get("stay_search_request_id"), str):
        ssr = next((r for r in ssrs if isinstance(r, dict) and r.get("id") == prop.get("stay_search_request_id")), None)

    # Freshness window: 24h
    freshness = datetime.timedelta(hours=24)
    cached_at = _parse_dt(prop.get("reviews_cached_at"))
    cache_fresh = cached_at is not None and (now - cached_at) < freshness

    mutated = False

    # If unavailable, return cached (if any) but do not attempt refresh offline
    if prop.get("status") == "unavailable":
        out = {
            "stay_property_id": prop.get("id"),
            "provider_property_id": prop.get("provider_property_id"),
            "status": prop.get("status"),
            "review_summary": prop.get("review_summary") if isinstance(prop.get("review_summary"), dict) else _compute_review_summary(prop.get("reviews_cache")),
            "reviews": prop.get("reviews_cache") if isinstance(prop.get("reviews_cache"), list) else [],
            "reviews_cached_at": prop.get("reviews_cached_at"),
            "_meta": {
                "cache_fresh": cache_fresh,
                "session_status": sess.get("status") if isinstance(sess, dict) else None,
                "stay_search_request_status": ssr.get("status") if isinstance(ssr, dict) else None,
            },
        }
        _log("OK", {"stay_property_id": stay_property_id, "mutated": False, "status": "unavailable"})
        return {"data": out}

    # If cache is fresh, return it
    if cache_fresh and isinstance(prop.get("reviews_cache"), list):
        if not isinstance(prop.get("review_summary"), dict):
            prop["review_summary"] = _compute_review_summary(prop.get("reviews_cache"))
            prop["updated_at"] = _iso(now)
            mutated = True
        if mutated:
            _save("stay_properties.json", props)
        out = {
            "stay_property_id": prop.get("id"),
            "provider_property_id": prop.get("provider_property_id"),
            "status": prop.get("status"),
            "review_summary": prop.get("review_summary"),
            "reviews": prop.get("reviews_cache"),
            "reviews_cached_at": prop.get("reviews_cached_at"),
            "_meta": {
                "cache_fresh": True,
                "session_status": sess.get("status") if isinstance(sess, dict) else None,
                "stay_search_request_status": ssr.get("status") if isinstance(ssr, dict) else None,
            },
        }
        _log("OK", {"stay_property_id": stay_property_id, "mutated": mutated, "cache_fresh": True})
        return {"data": out}

    # Cache is missing or stale; offline "refresh" cannot call provider.
    # Realistic behavior: mark property stale (legal active->stale) and return whatever cached data exists.
    if prop.get("status") == "active":
        prop["status"] = "stale"
        prop["updated_at"] = _iso(now)
        mutated = True

    # If no cached reviews exist at all, keep as stale but return empty set (not NOT_FOUND because property exists)
    if not isinstance(prop.get("reviews_cache"), list):
        prop["reviews_cache"] = []
        mutated = True
    if not isinstance(prop.get("review_summary"), dict):
        prop["review_summary"] = _compute_review_summary(prop.get("reviews_cache"))
        mutated = True
    if prop.get("reviews_cached_at") is None:
        # Record attempted refresh time as cached_at to avoid reattempt loops in tests (still stale)
        prop["reviews_cached_at"] = _iso(now)
        mutated = True

    if mutated:
        _save("stay_properties.json", props)

    out = {
        "stay_property_id": prop.get("id"),
        "provider_property_id": prop.get("provider_property_id"),
        "status": prop.get("status"),
        "review_summary": prop.get("review_summary"),
        "reviews": prop.get("reviews_cache"),
        "reviews_cached_at": prop.get("reviews_cached_at"),
        "_meta": {
            "cache_fresh": False,
            "session_status": sess.get("status") if isinstance(sess, dict) else None,
            "stay_search_request_status": ssr.get("status") if isinstance(ssr, dict) else None,
            "refresh": "offline_no_upstream_call",
        },
    }

    _log("OK", {"stay_property_id": stay_property_id, "mutated": mutated, "cache_fresh": False, "status": out.get("status")})
    return {"data": out}

def list_search_sessions(api_key, session_type=None, status=None, provider=None, client_request_id=None, created_at_gte=None, created_at_lte=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, random, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0314000" if __import__("os").path.isdir("./environment_mix/0314000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    started = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _log(status_s, credential=None, meta=None):
        meta = meta or {}
        row = {
            "id": "fss_req_" + "".join(random.choice("0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ") for _ in range(18)),
            "endpoint": "list_search_sessions",
            "credential": credential,
            "status": status_s,
            "latency_ms": int((time.time() - started) * 1000),
            "timestamp": now.isoformat().replace("+00:00", "Z"),
            "meta": meta,
        }
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(row)
        _save("request_logs.json", logs)

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            if v.tzinfo is None:
                return v.replace(tzinfo=datetime.timezone.utc)
            return v.astimezone(datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s)
        except Exception:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    # Validate api_key (authenticate by id or client-visible value-like field; never hash compare)
    if not isinstance(api_key, str) or not api_key.strip():
        _log("VALIDATION_ERROR", None, {"field": "api_key"})
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string", field="api_key")

    # Soft-auth: accept if api_keys.json exists and contains match, else (for offline) allow any non-empty key
    creds = _load("api_keys.json")
    cred_row = None
    if isinstance(creds, list) and creds:
        for c in creds:
            if not isinstance(c, dict):
                continue
            if api_key in (c.get("id"), c.get("value"), c.get("api_key"), c.get("key")):
                if c.get("status") in (None, "active", "enabled"):
                    cred_row = c
                    break
        if cred_row is None:
            _log("UNAUTHORIZED", api_key, {"reason": "api_key not found"})
            return _err("UNAUTHORIZED", "Invalid API key")
    else:
        cred_row = {"id": api_key}

    # Validate filters
    if session_type is not None and session_type not in ("flight", "multi_city", "stay"):
        _log("VALIDATION_ERROR", cred_row.get("id"), {"field": "session_type"})
        return _err("VALIDATION_ERROR", "session_type must be one of flight, multi_city, stay", field="session_type")
    if status is not None and status not in ("created", "running", "completed", "failed", "expired", "cancelled"):
        _log("VALIDATION_ERROR", cred_row.get("id"), {"field": "status"})
        return _err("VALIDATION_ERROR", "status must be one of created, running, completed, failed, expired, cancelled", field="status")
    if provider is not None and provider not in ("duffel", "hotel_provider"):
        _log("VALIDATION_ERROR", cred_row.get("id"), {"field": "provider"})
        return _err("VALIDATION_ERROR", "provider must be one of duffel, hotel_provider", field="provider")
    if client_request_id is not None and not isinstance(client_request_id, str):
        _log("VALIDATION_ERROR", cred_row.get("id"), {"field": "client_request_id"})
        return _err("VALIDATION_ERROR", "client_request_id must be a string", field="client_request_id")

    gte = _parse_dt(created_at_gte) if created_at_gte is not None else None
    lte = _parse_dt(created_at_lte) if created_at_lte is not None else None
    if created_at_gte is not None and gte is None:
        _log("VALIDATION_ERROR", cred_row.get("id"), {"field": "created_at_gte"})
        return _err("VALIDATION_ERROR", "created_at_gte must be an RFC3339 datetime", field="created_at_gte")
    if created_at_lte is not None and lte is None:
        _log("VALIDATION_ERROR", cred_row.get("id"), {"field": "created_at_lte"})
        return _err("VALIDATION_ERROR", "created_at_lte must be an RFC3339 datetime", field="created_at_lte")

    if limit is None:
        limit = 20
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log("VALIDATION_ERROR", cred_row.get("id"), {"field": "limit"})
        return _err("VALIDATION_ERROR", "limit must be between 1 and 100", field="limit")

    start = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            _log("VALIDATION_ERROR", cred_row.get("id"), {"field": "cursor"})
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string", field="cursor")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            if raw.startswith("offset:"):
                start = int(raw.split(":", 1)[1])
            else:
                _log("VALIDATION_ERROR", cred_row.get("id"), {"field": "cursor"})
                return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")
        except Exception:
            _log("VALIDATION_ERROR", cred_row.get("id"), {"field": "cursor"})
            return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")
        if start < 0:
            start = 0

    sessions = _load("search_sessions.json")
    if not isinstance(sessions, list):
        sessions = []

    # Filter
    out = []
    for s in sessions:
        if not isinstance(s, dict):
            continue
        if session_type is not None and s.get("session_type") != session_type:
            continue
        if status is not None and s.get("status") != status:
            continue
        if provider is not None and s.get("provider") != provider:
            continue
        if client_request_id is not None and s.get("client_request_id") != client_request_id:
            continue
        ca = _parse_dt(s.get("created_at"))
        if gte is not None and (ca is None or ca < gte):
            continue
        if lte is not None and (ca is None or ca > lte):
            continue
        out.append(s)

    # Order by created_at desc (fallback: id desc)
    out.sort(key=lambda r: (_parse_dt(r.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc), r.get("id") or ""), reverse=True)

    total = len(out)
    page = out[start:start + limit]
    has_more = (start + limit) < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"offset:{start + limit}".encode("utf-8")).decode("utf-8")

    _log("OK", cred_row.get("id"), {"returned": len(page), "total": total})
    return {"data": {"sessions": page, "meta": {"total": total, "limit": limit, "cursor": cursor, "has_more": has_more, "next_cursor": next_cursor}}}

def get_search_session(api_key, session_id, include_results=None, **_extra):
