    sess = next((s for s in sessions if isinstance(s, dict) and s.get("id") == session_id), None)
    if not sess:
        _log("NOT_FOUND", cred_row.get("id"), {"session_id": session_id})
        return _err("NOT_FOUND", "Search session not found", session_id=session_id)

    # If expired by time, refuse serving results; still return session metadata.
    exp = _parse_dt(sess.get("expires_at"))
    is_expired_time = (exp is not None and now >= exp)

    data = {"session": sess}
    if include_results:
        if sess.get("session_type") in ("flight", "multi_city"):
            fsrs = _load("flight_search_requests.json")
            if not isinstance(fsrs, list):
                fsrs = []
            fsr = next((r for r in fsrs if isinstance(r, dict) and r.get("session_id") == session_id), None)
            data["flight_search_request"] = fsr
            if not is_expired_time:
                offers = _load("flight_offers.json")
                if not isinstance(offers, list):
                    offers = []
                sess_offers = [o for o in offers if isinstance(o, dict) and o.get("session_id") == session_id]
                if len(sess_offers) > 500:
                    sess_offers = sess_offers[:500]
                data["offers"] = sess_offers
            else:
                data["offers"] = []
                data["results_blocked_reason"] = "expired"
        elif sess.get("session_type") == "stay":
            ssrs = _load("stay_search_requests.json")
            if not isinstance(ssrs, list):
                ssrs = []
            ssr = next((r for r in ssrs if isinstance(r, dict) and r.get("session_id") == session_id), None)
            data["stay_search_request"] = ssr
            if not is_expired_time:
                props = _load("stay_properties.json")
                if not isinstance(props, list):
                    props = []
                sess_props = [p for p in props if isinstance(p, dict) and p.get("session_id") == session_id]
                if len(sess_props) > 500:
                    sess_props = sess_props[:500]
                data["properties"] = sess_props
            else:
                data["properties"] = []
                data["results_blocked_reason"] = "expired"

    _log("OK", cred_row.get("id"), {"session_id": session_id, "include_results": include_results, "expired": bool(is_expired_time)})
    return {"data": data}

def cancel_search_session(api_key, session_id, reason=None, **_extra):
    import json, os, datetime, time, random, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0314000" if __import__("os").path.isdir("./environment_mix/0314000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if not isinstance(dt, datetime.datetime):
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _log(status, credential=None, meta=None):
        meta = meta or {}
        row = {
            "id": "fss_req_" + "".join(random.choice("0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ") for _ in range(18)),
            "endpoint": "cancel_search_session",
            "credential": credential,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _iso(now),
            "meta": meta,
        }
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(row)
        _save("request_logs.json", logs)

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        _log("VALIDATION_ERROR", None, {"field": "api_key"})
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string", field="api_key")
    if not isinstance(session_id, str) or not session_id.strip():
        _log("VALIDATION_ERROR", api_key, {"field": "session_id"})
        return _err("VALIDATION_ERROR", "session_id must be a non-empty string", field="session_id")
    session_id = session_id.strip()
    if not re.match(r"^fss_sess_[0-9A-Z]{18,}$", session_id):
        _log("VALIDATION_ERROR", api_key, {"field": "session_id", "rule": "pattern"})
        return _err("VALIDATION_ERROR", "session_id does not match required pattern '^fss_sess_[0-9A-Z]{18,}$'", field="session_id", rule="pattern")
    if reason is not None and not isinstance(reason, str):
        _log("VALIDATION_ERROR", api_key, {"field": "reason"})
        return _err("VALIDATION_ERROR", "reason must be a string", field="reason")

    # Authenticate api_key if api_keys.json exists and is populated. Otherwise ambient-auth allow.
    creds = _load("api_keys.json")
    credential_used = api_key.strip()
    if isinstance(creds, list) and creds:
        ok = False
        for c in creds:
            if not isinstance(c, dict):
                continue
            # Match by client-visible value or id (never by hash)
            if c.get("id") == api_key or c.get("api_key") == api_key or c.get("value") == api_key or c.get("key") == api_key:
                ok = True
                credential_used = c.get("id") or api_key
                break
        if not ok:
            _log("UNAUTHORIZED", api_key, {"rule": "api_key must match an existing key"})
            return _err("UNAUTHORIZED", "Invalid api_key", rule="api_key must match an existing key")

    sessions = _load("search_sessions.json")
    if not isinstance(sessions, list):
        sessions = []

    sess = next((s for s in sessions if isinstance(s, dict) and s.get("id") == session_id), None)
    if not sess:
        _log("NOT_FOUND", credential_used, {"session_id": session_id})
        return _err("NOT_FOUND", "Search session not found", session_id=session_id)

    status = sess.get("status")
    allowed = {"created", "running"}
    if status not in allowed:
        # Relaxed rule per audit: accept and persist a no-op cancellation marker rather than reject.
        # Real systems often allow "cancel" to be idempotent: return current session and record the attempt.
        audit = sess.get("cancellation") if isinstance(sess.get("cancellation"), dict) else {}
        audit.update({
            "attempted": True,
            "attempted_at": _iso(now),
            "reason": reason if isinstance(reason, str) and reason.strip() else audit.get("reason"),
        })
        sess["cancellation"] = audit
        sess["updated_at"] = _iso(now)
        _save("search_sessions.json", sessions)
        _log("OK", credential_used, {"session_id": session_id, "idempotent": True, "status": status})
        return {"data": sess}

    # Enforce lifecycle transition created|running -> cancelled
    sess["status"] = "cancelled"
    sess["updated_at"] = _iso(now)
    # Record cancellation auditing fields (non-schema fields allowed)
    sess["cancellation"] = {
        "cancelled_at": _iso(now),
        "reason": reason if isinstance(reason, str) and reason.strip() else None,
    }

    # Cascade: mark associated request(s) failed if pending/submitted; offers/properties can remain cached but session is cancelled
    fsrs = _load("flight_search_requests.json")
    if not isinstance(fsrs, list):
        fsrs = []
    ssrs = _load("stay_search_requests.json")
    if not isinstance(ssrs, list):
        ssrs = []

    changed_child = False
    for r in fsrs:
        if isinstance(r, dict) and r.get("session_id") == session_id:
            if r.get("status") in ("pending", "submitted"):
                r["status"] = "failed"
                r["updated_at"] = _iso(now)
                changed_child = True
    for r in ssrs:
        if isinstance(r, dict) and r.get("session_id") == session_id:
            if r.get("status") in ("pending", "submitted"):
                r["status"] = "failed"
                r["updated_at"] = _iso(now)
                changed_child = True

    _save("search_sessions.json", sessions)
    if changed_child:
        _save("flight_search_requests.json", fsrs)
        _save("stay_search_requests.json", ssrs)

    _log("OK", credential_used, {"session_id": session_id, "new_status": "cancelled", "children_updated": changed_child})
    return {"data": sess}

def expire_search_session(api_key, session_id, force=None, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0314000" if __import__("os").path.isdir("./environment_mix/0314000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, (int, float)):
            return datetime.datetime.fromtimestamp(v, tz=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                return datetime.datetime.fromisoformat(s)
            except ValueError:
                return None
        return None

    def _ensure_request_log_schema(logs):
        # list of dicts
        if not isinstance(logs, list):
            return []
        return logs

    def _log(endpoint, credential_id, status, error_code=None):
        logs = _ensure_request_log_schema(_load("request_logs.json"))
        row = {
            "id": "req_" + hashlib.sha1(f"{endpoint}|{credential_id}|{_now_iso()}|{time.time()}".encode("utf-8")).hexdigest()[:20],
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _now_iso(),
        }
        logs.append(row)
        _save("request_logs.json", logs)
        return row

    def _find_credential(api_key_value):
        creds = _load("api_keys.json")
        if not isinstance(creds, list):
            creds = []
        for c in creds:
            if not isinstance(c, dict):
                continue
            if c.get("id") == api_key_value or c.get("api_key") == api_key_value or c.get("key") == api_key_value or c.get("value") == api_key_value:
                return c
        return None

    def _auth_or_fallback(api_key_value):
        cred = _find_credential(api_key_value)
        if cred is not None:
            if cred.get("revoked") is True or cred.get("status") in ("revoked", "disabled", "inactive"):
                return None, _err("UNAUTHORIZED", "Credential is revoked or inactive.")
            return cred, None
        # If no credential store exists, allow a single-tenant offline mode only when no api_keys.json is present.
        if not os.path.exists(os.path.join(_DB, "api_keys.json")):
            return {"id": "offline_default", "scopes": ["*"]}, None
        return None, _err("UNAUTHORIZED", "Invalid API key.")

    def _rate_limit_check(credential_id):
        # If no request log store, skip enforcement
        log_path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(log_path):
            return None
        logs = _load("request_logs.json")
        logs = _ensure_request_log_schema(logs)
        now = datetime.datetime.now(datetime.timezone.utc)
        # basic: 120 requests/minute per credential
        window = datetime.timedelta(seconds=60)
        cutoff = now - window
        cnt = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("credential_id") != credential_id:
                continue
            ts = _parse_dt(r.get("created_at"))
            if ts is None:
                continue
            if ts >= cutoff:
                cnt += 1
        if cnt >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded.", limit=120, window_seconds=60)
        return None

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string.")
    if not isinstance(session_id, str) or not re.match(r"^fss_sess_[0-9A-Z]{18,}$", session_id):
        return _err("VALIDATION_ERROR", "session_id is invalid.")
    if force is None:
        force = False
    if not isinstance(force, bool):
        return _err("VALIDATION_ERROR", "force must be a boolean.")

    cred, auth_err = _auth_or_fallback(api_key)
    if auth_err:
        # best-effort logging
        try:
            _log("expire_search_session", None, "error", error_code=auth_err["error"]["code"])
        except Exception:
            pass
        return auth_err

    rl_err = _rate_limit_check(cred.get("id"))
    if rl_err:
        try:
            _log("expire_search_session", cred.get("id"), "error", error_code=rl_err["error"]["code"])
        except Exception:
            pass
        return rl_err

    sessions = _load("search_sessions.json")
    if not isinstance(sessions, list):
        sessions = []

    sess = None
    idx = None
    for i, s in enumerate(sessions):
        if isinstance(s, dict) and s.get("id") == session_id:
            sess, idx = s, i
            break
    if sess is None:
        _log("expire_search_session", cred.get("id"), "error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Search session not found.")

    status = sess.get("status")
    if status not in ("completed", "failed"):
        _log("expire_search_session", cred.get("id"), "error", error_code="INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Session is not eligible for expiration.", current_status=status, allowed_from=["completed", "failed"])

    now = datetime.datetime.now(datetime.timezone.utc)
    exp = _parse_dt(sess.get("expires_at"))
    if exp is None:
        _log("expire_search_session", cred.get("id"), "error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Session expires_at is missing or invalid in datastore.")
    if (not force) and now < exp:
        _log("expire_search_session", cred.get("id"), "error", error_code="INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Session cannot be expired before expires_at unless force=true.", expires_at=sess.get("expires_at"))

    # Transition to expired
    sess = dict(sess)
    sess["status"] = "expired"
    sess["updated_at"] = _now_iso()
    sessions[idx] = sess
    _save("search_sessions.json", sessions)

    _log("expire_search_session", cred.get("id"), "ok", error_code=None)
    return {"data": sess}

def list_flight_offers(api_key, session_id=None, flight_search_request_id=None, status=None, provider=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, random, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0314000" if __import__("os").path.isdir("./environment_mix/0314000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            if v.tzinfo is None:
                return v.replace(tzinfo=datetime.timezone.utc)
            return v.astimezone(datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
            except Exception:
                return None
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        return None

    def _log(status_str, credential=None, meta=None):
        meta = meta or {}
        row = {
            "id": "fss_req_" + "".join(random.choice("0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ") for _ in range(18)),
            "endpoint": "list_flight_offers",
            "credential": credential,
            "status": status_str,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _iso(now),
            "meta": meta,
        }
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(row)
        _save("request_logs.json", logs)

    try:
        # Validate api_key
        if not isinstance(api_key, str) or not api_key.strip():
            _log("VALIDATION_ERROR", None, {"field": "api_key"})
            return _err("VALIDATION_ERROR", "api_key must be a non-empty string", field="api_key")

        # Authenticate api_key if store exists; else ambient accept.
        creds = _load("api_keys.json")
        cred_row = None
        if isinstance(creds, list):
            for c in creds:
                if not isinstance(c, dict):
                    continue
                if api_key in (c.get("id"), c.get("value"), c.get("api_key"), c.get("key")):
                    cred_row = c
                    break
        if isinstance(creds, list) and len(creds) > 0 and cred_row is None:
            _log("UNAUTHORIZED", api_key, {"rule": "api_key must match a stored credential"})
            return _err("UNAUTHORIZED", "Invalid api_key", api_key=api_key)

        if session_id is not None:
            if not isinstance(session_id, str) or not re.match(r"^fss_sess_[0-9A-Z]{18,}$", session_id.strip()):
                _log("VALIDATION_ERROR", api_key, {"field": "session_id"})
                return _err("VALIDATION_ERROR", "session_id does not match required format", field="session_id")
            session_id = session_id.strip()

        if flight_search_request_id is not None:
            if not isinstance(flight_search_request_id, str) or not re.match(r"^fss_fsr_[0-9A-Z]{18,}$", flight_search_request_id.strip()):
                _log("VALIDATION_ERROR", api_key, {"field": "flight_search_request_id"})
                return _err("VALIDATION_ERROR", "flight_search_request_id does not match required format", field="flight_search_request_id")
            flight_search_request_id = flight_search_request_id.strip()

        if status is not None and status not in ("active", "stale", "invalid"):
            _log("VALIDATION_ERROR", api_key, {"field": "status"})
            return _err("VALIDATION_ERROR", "status must be one of: active, stale, invalid", field="status")

        if provider is not None and provider not in ("duffel",):
            _log("VALIDATION_ERROR", api_key, {"field": "provider"})
            return _err("VALIDATION_ERROR", "provider must be 'duffel' when provided", field="provider")

        if limit is None:
            limit = 50
        if not isinstance(limit, int) or limit < 1 or limit > 100:
            _log("VALIDATION_ERROR", api_key, {"field": "limit"})
            return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100", field="limit")

        # Resolve references if provided; reject mismatch when both provided
        sessions = _load("search_sessions.json")
        if not isinstance(sessions, list):
            sessions = []
        fsrs = _load("flight_search_requests.json")
        if not isinstance(fsrs, list):
            fsrs = []
        offers = _load("flight_offers.json")
        if not isinstance(offers, list):
            offers = []

        sess = None
        if session_id is not None:
            sess = next((s for s in sessions if isinstance(s, dict) and s.get("id") == session_id), None)
            if sess is None:
                _log("NOT_FOUND", api_key, {"session_id": session_id})
                return _err("NOT_FOUND", "No search session found for the given session_id", session_id=session_id)

            # Enforce "refuse expired sessions" (configuration: default refuse)
            expires_at = _parse_dt(sess.get("expires_at"))
            if expires_at and now >= expires_at:
                # update status if eligible
                if sess.get("status") in ("completed", "failed"):
                    sess["status"] = "expired"
                    sess["updated_at"] = _iso(now)
                    for i, s in enumerate(sessions):
                        if isinstance(s, dict) and s.get("id") == sess["id"]:
                            sessions[i] = sess
                            break
                    _save("search_sessions.json", sessions)
                _log("INVALID_TRANSITION", api_key, {"session_id": session_id, "rule": "refuse expired sessions"})
                return _err("INVALID_TRANSITION", "Cannot list offers for an expired session", session_id=session_id, status=sess.get("status"))

        fsr = None
        if flight_search_request_id is not None:
            fsr = next((r for r in fsrs if isinstance(r, dict) and r.get("id") == flight_search_request_id), None)
            if fsr is None:
                _log("NOT_FOUND", api_key, {"flight_search_request_id": flight_search_request_id})
                return _err("NOT_FOUND", "No flight_search_request found for the given flight_search_request_id", flight_search_request_id=flight_search_request_id)
            if session_id is not None and fsr.get("session_id") != session_id:
                _log("VALIDATION_ERROR", api_key, {"field": "flight_search_request_id"})
                return _err("VALIDATION_ERROR", "flight_search_request_id must belong to the provided session_id", field="flight_search_request_id")

        # Cursor decode: base64 of integer offset
        offset = 0
        if cursor is not None:
            if not isinstance(cursor, str) or not cursor.strip():
                _log("VALIDATION_ERROR", api_key, {"field": "cursor"})
                return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided", field="cursor")
            try:
                offset = int(base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===").decode("utf-8"))
                if offset < 0:
                    offset = 0
            except Exception:
                _log("VALIDATION_ERROR", api_key, {"field": "cursor"})
                return _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")

        # Filter offers
        filtered = []
        for o in offers:
            if not isinstance(o, dict):
                continue
            if session_id is not None and o.get("session_id") != session_id:
                continue
            if flight_search_request_id is not None and o.get("flight_search_request_id") != flight_search_request_id:
                continue
            if status is not None and o.get("status") != status:
                continue
            if provider is not None and o.get("provider") != provider:
                continue
            filtered.append(o)

        # Sort: newest first
        def _sort_key(o):
            dt = _parse_dt(o.get("created_at")) or _parse_dt(o.get("updated_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
            return dt
        filtered.sort(key=_sort_key, reverse=True)

        total = len(filtered)
        page = filtered[offset:offset + limit]
        next_offset = offset + len(page)
        has_more = next_offset < total
        next_cursor = None
        if has_more:
            next_cursor = base64.urlsafe_b64encode(str(next_offset).encode("utf-8")).decode("utf-8").rstrip("=")

        _log("OK", api_key, {"total": total, "returned": len(page), "has_more": has_more})
        return {
            "data": {
                "offers": page,
                "meta": {
                    "total": total,
                    "limit": limit,
                    "cursor": cursor,
                    "next_cursor": next_cursor,
                    "has_more": has_more
                }
            }
        }
    except Exception as e:
        _log("ERROR", api_key, {"exception": type(e).__name__})
        return _err("CONFLICT", "Unexpected error while listing flight offers")

def get_whoami(api_key, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0314000" if __import__("os").path.isdir("./environment_mix/0314000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, (int, float)):
            return datetime.datetime.fromtimestamp(v, tz=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                return datetime.datetime.fromisoformat(s)
            except ValueError:
                return None
        return None

    def _ensure_request_log_schema(logs):
        if not isinstance(logs, list):
            return []
        return logs

    def _log(endpoint, credential_id, status_str, error_code=None):
        logs = _ensure_request_log_schema(_load("request_logs.json"))
        row = {
            "id": "req_" + hashlib.sha1(f"{endpoint}|{credential_id}|{_now_iso()}|{time.time()}".encode("utf-8")).hexdigest()[:20],
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status_str,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _now_iso(),
        }
        logs.append(row)
        _save("request_logs.json", logs)
        return row

    def _find_credential(api_key_value):
        creds = _load("api_keys.json")
        if not isinstance(creds, list):
            creds = []
        for c in creds:
            if not isinstance(c, dict):
                continue
            if c.get("id") == api_key_value or c.get("api_key") == api_key_value or c.get("key") == api_key_value or c.get("value") == api_key_value:
                return c
        return None

    def _auth(api_key_value):
        cred = _find_credential(api_key_value)
        if cred is None:
            if not os.path.exists(os.path.join(_DB, "api_keys.json")):
                return {"id": "offline_default", "scopes": ["*"], "status": "active"}, None
            return None, _err("UNAUTHORIZED", "Invalid API key.")
        if cred.get("revoked") is True or cred.get("status") in ("revoked", "disabled", "inactive"):
            return None, _err("UNAUTHORIZED", "Credential is revoked or inactive.")
        return cred, None

    def _rate_limit_check(credential_id):
        log_path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(log_path):
            return None
        logs = _ensure_request_log_schema(_load("request_logs.json"))
        now = datetime.datetime.now(datetime.timezone.utc)
        window = datetime.timedelta(seconds=60)
        cutoff = now - window
        cnt = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("credential_id") != credential_id:
                continue
            ts = _parse_dt(r.get("created_at"))
            if ts is None:
                continue
            if ts >= cutoff:
                cnt += 1
        if cnt >= 60:
            return _err("RATE_LIMIT", "Rate limit exceeded.", limit=60, window_seconds=60)
        return None

    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string.")

    cred, auth_err = _auth(api_key)
    if auth_err:
        try:
            _log("get_whoami", None, "error", error_code=auth_err["error"]["code"])
        except Exception:
            pass
        return auth_err

    rl_err = _rate_limit_check(cred.get("id"))
    if rl_err:
        try:
            _log("get_whoami", cred.get("id"), "error", error_code=rl_err["error"]["code"])
        except Exception:
            pass
        return rl_err

    # Compute consumption from request logs
    logs = _ensure_request_log_schema(_load("request_logs.json"))
    now = datetime.datetime.now(datetime.timezone.utc)
    last_min_cutoff = now - datetime.timedelta(seconds=60)
    last_day_cutoff = now - datetime.timedelta(days=1)

    used_last_min = 0
    used_last_day = 0
    for r in logs:
        if not isinstance(r, dict):
            continue
        if r.get("credential_id") != cred.get("id"):
            continue
        ts = _parse_dt(r.get("created_at"))
        if ts is None:
            continue
        if ts >= last_min_cutoff:
            used_last_min += 1
        if ts >= last_day_cutoff:
            used_last_day += 1

    # Default quotas (can be overridden by fields on credential if present)
    rate_limit_per_min = cred.get("rate_limit_per_minute")
    if not isinstance(rate_limit_per_min, int) or rate_limit_per_min <= 0:
        rate_limit_per_min = 60

    quota_per_day = cred.get("quota_per_day")
    if not isinstance(quota_per_day, int) or quota_per_day <= 0:
        quota_per_day = 5000

    remaining_min = max(0, rate_limit_per_min - used_last_min)
    remaining_day = max(0, quota_per_day - used_last_day)

    identity = {
        "credential": {
            "id": cred.get("id"),
            "name": cred.get("name"),
            "status": cred.get("status", "active"),
            "scopes": cred.get("scopes", ["*"]) if isinstance(cred.get("scopes", ["*"]), list) else ["*"],
        },
        "limits": {
            "rate_limit": {"limit_per_minute": rate_limit_per_min, "used_last_minute": used_last_min, "remaining": remaining_min},
            "quota": {"limit_per_day": quota_per_day, "used_last_24h": used_last_day, "remaining": remaining_day},
        }
    }

    _log("get_whoami", cred.get("id"), "ok", error_code=None)
    return {"data": identity}
